node -e "
const today = new Date();
const dayOfWeek = today.getDay(); // 0=Sun, 1=Mon, ..., 3=Wed
let daysAhead = 3 - dayOfWeek; // Wednesday = 3
if (daysAhead <= 0) daysAhead += 7;
const nextWed = new Date(today);
nextWed.setDate(today.getDate() + daysAhead);
const y = nextWed.getFullYear();
const m = String(nextWed.getMonth()+1).padStart(2,'0');
const d = String(nextWed.getDate()).padStart(2,'0');
console.log(y + m + d);
"
